-- Idempotency keys for no-op set_slot / clear_slot (no version bump, no event).
-- Retried no-ops must not re-evaluate after a later write (platform#46 review).
-- Applied migrations are immutable: do not edit this file after it has been applied;
-- ship a new numbered migration instead (see src/db/migrate.ts checksum guard).
CREATE TABLE IF NOT EXISTS gear_op_noop_ids (
  guild_id         UUID NOT NULL REFERENCES guilds(id) ON DELETE CASCADE,
  idempotency_key  TEXT NOT NULL,
  list_id          UUID NOT NULL REFERENCES gear_lists(id) ON DELETE CASCADE,
  recorded_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (guild_id, idempotency_key)
);

CREATE INDEX IF NOT EXISTS gear_op_noop_ids_list_idx ON gear_op_noop_ids (list_id);

GRANT SELECT, INSERT ON gear_op_noop_ids TO crusaderstrike_app;
GRANT ALL ON gear_op_noop_ids TO crusaderstrike_migrate;

ALTER TABLE gear_op_noop_ids ENABLE ROW LEVEL SECURITY;
ALTER TABLE gear_op_noop_ids FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS gear_op_noop_ids_tenant ON gear_op_noop_ids;
CREATE POLICY gear_op_noop_ids_tenant ON gear_op_noop_ids
  USING (guild_id = app_current_guild_id())
  WITH CHECK (guild_id = app_current_guild_id());
